manifest_content:
{
  "name": "@dietrichgebert/ponytail",
  "version": "5.3.3",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "ponytail", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/DietrichGebert/ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DietrichGebert/ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/DietrichGebert/ponytail/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "!pi-extension/test/",
    "scripts/uninstall.js",
    "scripts/cursor-hooks.js",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}

{
  "name": "antigravity2-cn",
  "license": "MIT",
  "private": true,
  "scripts": {
    "test": "node --test tests/*-regressions.cjs"
  },
  "devDependencies": {
    "jsdom": "30.1.3"
  }
}

{
  "private": true,
  "name": "@appwrite.io/repo",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/appwrite/appwrite.git"
  },
  "scripts": {
    "format:compose": "prettier --write docker-compose.yml docker-compose.override.yml",
    "lint:compose": "prettier --check docker-compose.yml docker-compose.override.yml"
  },
  "files": [
    "docs/examples",
    "app/config/specs"
  ],
  "devDependencies": {
    "prettier": "^3.9.0"
  }
}

{
  "name": "@vercel-labs/agent-skills",
  "private": true,
  "type": "module",
  "dependencies": {
    "yaml": "2.9.0"
  }
}

{
  "name": "pstack",
  "private": true,
  "version": "0.9.155",
  "description": "If you want to go fast, go deep first. pstack helps you write less, but higher quality code. rigorous agent workflows you can parallelize with confidence. Pi and OpenCode package of the Claude Code plugin; skills are shared, and runtime mappings translate tool names. Original pstack by Lauren Tan (poteto).",
  "author": {
    "name": "Michael Denyer",
    "url": "https://github.com/michael-denyer"
  },
  "homepage": "https://github.com/michael-denyer/pstack-claude",
  "repository": "https://github.com/michael-denyer/pstack-claude",
  "license": "MIT",
  "keywords": [
    "pi-package",
    "pstack",
    "poteto-mode",
    "workflow",
    "principles",
    "agent-style",
    "subagents",
    "unslop",
    "claude-code",
    "skills",
    "tdd",
    "code-review",
    "parallel-agents",
    "codex",
    "opencode",
    "gemini-cli",
    "prime-agent"
  ],
  "pi": {
    "skills": [
      "./plugins/pstack/skills"
    ],
    "extensions": [
      "./plugins/pstack/pi/index.ts"
    ]
  },
  "exports": {
    "./server": "./plugins/pstack/opencode/index.js"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    }
  }
}
